<script lang="ts">
	import { apiFetch } from '$lib/api/client'; import type { CatalogSetDetail, MissingPart, OwnedSet } from '$lib/api/types';
	let { owned, onClose, onSaved }: { owned: OwnedSet; onClose: () => void; onSaved: (total: number) => void } = $props(); let detail = $state<CatalogSetDetail | null>(null); let missing = $state<MissingPart[]>([]); let selected = $state<CatalogSetDetail['parts'][number] | null>(null); let quantity = $state(1); let note = $state('');
	$effect(() => { void load(); }); async function load(){ detail = await apiFetch<CatalogSetDetail>(`/api/catalog/sets/${owned.set_num}`); missing = await apiFetch<MissingPart[]>(`/api/collection/${owned.id}/missing-parts`); }
	async function save(){ if (!selected) return; await apiFetch(`/api/collection/${owned.id}/missing-parts`,{method:'POST',body:{part_num:selected.part_num,color_id:selected.color_id,quantity,note:note||null}}); const all=await apiFetch<MissingPart[]>(`/api/collection/${owned.id}/missing-parts`); onSaved(all.reduce((sum,item)=>sum+item.quantity,0)); selected=null; missing=all; }
</script>
<div class="backdrop" role="presentation"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="missing-title"><header><h2 id="missing-title">Missing pieces · {owned.set_name}</h2><button aria-label="Close" onclick={onClose}>×</button></header>{#if detail}<div class="part-list">{#each detail.parts.filter((part) => !part.is_spare) as part}<button onclick={() => { selected = part; quantity = 1; }}><i style={`background:#${part.rgb_hex}`}></i>{part.part_name} · {part.color_name}</button>{/each}</div>{/if}{#if selected}<form onsubmit={(e)=>{e.preventDefault();void save();}}><h3>{selected.part_name}</h3><label>Missing quantity <input aria-label="Missing quantity" type="number" min="1" bind:value={quantity} /></label><label>Note <input bind:value={note} /></label><button>Save missing piece</button></form>{/if}</div></div>
<style>.backdrop{position:fixed;inset:0;z-index:5;overflow:auto;padding:16px;background:#17171766}.dialog{max-width:620px;margin:6vh auto;padding:20px;background:var(--surface);border:1px solid var(--ink);box-shadow:6px 6px 0 #171717}.dialog header{display:flex;justify-content:space-between;gap:8px}.dialog h2{margin:0 0 12px}.part-list{display:grid;max-height:280px;overflow:auto}.part-list button{text-align:left;padding:9px;border:1px solid var(--line);background:var(--surface)}i{display:inline-block;width:12px;height:12px;border:1px solid #555;margin-right:6px}form{display:grid;gap:10px;margin-top:14px;padding-top:14px;border-top:1px solid var(--line)}form h3{margin:0}label{display:grid;gap:4px;font-size:.82rem;font-weight:700}input{padding:7px;border:1px solid var(--line)}button{font:inherit;border:1px solid var(--ink);padding:7px 10px;background:var(--yellow);font-weight:700}</style>
